module Prob_5_46 (output y_out, input x_in, clk, reset_b);  reg [2:0] state, next_state;  assign y_out = (state == 3'b001)||(state == 3'b010) || (state == 3'b011);  always @ (posedge clk)    if (reset_b == 1'b0) state <= 3'b000; else state <= next_state;  always @ (x_in, state) begin    next_state = 3'b000;    case (state)      3'b000:	if (x_in) next_state = 3'b001; else next_state = 3'b000;      3'b001:	next_state = 3'b010;      3'b010:	next_state = 3'b011;      3'b011:	next_state = 3'b100;      3'b100:	next_state = 3'b101;      3'b101:	next_state = 3'b000;      default:	next_state = 3'b000;    endcase  endendmodulemodule t_Prob_5_46 ();  reg x_in, clk, reset_b;  wire y_out;  Prob_5_46 M0 (y_out, x_in, clk, reset_b);  initial #200 $finish;  initial begin clk = 0; forever #5 clk = !clk; end  initial fork    reset_b = 0;    #10 reset_b  = 1;    #80 reset_b = 0;    #90 reset_b = 1;    x_in = 0;    #30 x_in = 1;    #40 x_in = 1;    #50 x_in = 0;    #60 x_in = 1;    #70 x_in = 0;    #120 x_in = 1;    #130 x_in = 0;  joinendmodule